helpers.cm_powmod:
func cm_powmod(a int64, b int64, m int64) int64 {
	if b < 0 {
		a = cm_modinv(a, m)
		b = -b
	}
	r := cm_floormod(1, m)
	a = cm_floormod(a, m)
	for b > 0 {
		if b&1 == 1 {
			r = cm_floormod(r*a, m)
		}
		a = cm_floormod(a*a, m)
		b >>= 1
	}
	return r
}

helpers.cm_modinv:
func cm_modinv(a int64, m int64) int64 {
	n := m
	if n < 0 {
		n = -n
	}
	r0, r1 := cm_floormod(a, n), n
	s0, s1 := int64(1), int64(0)
	for r1 != 0 {
		q := r0 / r1
		r0, r1 = r1, r0-q*r1
		s0, s1 = s1, s0-q*s1
	}
	if r0 != 1 {
		panic("base is not invertible")
	}
	return cm_floormod(s0, n)
}
